import React, { useState } from 'react';
import Sidebar from './Sidebar';
import logo from '../logo.png';
import { 
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell,
  BarChart, Bar
} from 'recharts';

// --- ප්‍රස්තාර සඳහා දත්ත ---
const enrollmentData = [
  { month: 'Jan', students: 400 },
  { month: 'Feb', students: 600 },
  { month: 'Mar', students: 800 },
  { month: 'Apr', students: 750 },
  { month: 'May', students: 1000 },
  { month: 'Jun', students: 1250 },
];

const subjectData = [
  { name: 'Science', value: 450 },
  { name: 'Maths', value: 350 },
  { name: 'English', value: 250 },
  { name: 'IT', value: 200 },
];

const classDistributionData = [
  { grade: 'Grade 10', classes: 12 },
  { grade: 'Grade 11', classes: 15 },
  { grade: 'A/L 2026', classes: 10 },
  { grade: 'A/L 2027', classes: 8 },
];

const THEME_COLORS = ['#15803d', '#22c55e', '#1e293b', '#64748b'];

const weeklySchedule = [
  { time: "08:00 AM", mon: "O/L Science", tue: "-", wed: "O/L Science", thu: "-", fri: "Revision", sat: "O/L Maths", sun: "-" },
  { time: "10:30 AM", mon: "-", tue: "A/L Physics", wed: "-", thu: "A/L Physics", fri: "-", sat: "A/L Chem", sun: "A/L Physics" },
  { time: "01:00 PM", mon: "O/L Maths", tue: "-", wed: "O/L Maths", thu: "-", fri: "Paper Class", sat: "-", sun: "A/L Chem" },
  { time: "03:30 PM", mon: "-", tue: "A/L Chem", wed: "-", thu: "A/L Chem", fri: "-", sat: "English Lit", sun: "-" },
];

export default function LmsDashboard({ userName, handleLogout }) {
  const [currentSubPage, setCurrentSubPage] = useState('Overview');

  return (
    // overflow: 'hidden' මඟින් කිසිදු බාහිර scroll bar එකක් එන්න දෙන්නේ නැත
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', backgroundColor: '#f1f5f9', overflow: 'hidden', boxSizing: 'border-box' }}>
      
      {/* Top Header - උස 90px කර ලෝගෝ එක විශාල කරන ලදි */}
      <header style={{ 
        height: '90px', backgroundColor: '#ffffff', display: 'flex', 
        alignItems: 'center', justifyContent: 'space-between', padding: '0 40px', 
        borderBottom: '1px solid #e2e8f0', zIndex: 10,
        boxShadow: '0 2px 8px rgba(0,0,0,0.03)'
      }}>
        <img src={logo} alt="Logo" style={{ height: '62px', width: 'auto' }} /> 
        <div style={{ fontSize: '20px', fontWeight: '700', color: '#1e293b' }}>
          Welcome, {userName || 'Admin'} 👋
        </div>
        <div style={{ width: '45px', height: '45px', borderRadius: '50%', backgroundColor: '#cbd5e1' }} />
      </header>

      {/* Main Body */}
      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        
        {/* Sidebar Panel - overflowY hidden නිසා Logout එක හැමවෙලේම එකම තැන සුපිරියට පෙනේ */}
        <div style={{ 
          width: '260px', 
          backgroundColor: '#15803d', 
          display: 'flex', 
          flexDirection: 'column', 
          justifyContent: 'space-between',
          height: '100%',
          overflowY: 'hidden'
        }}>
          <div style={{ flex: 1, overflowY: 'hidden' }}>
            <Sidebar 
              currentSubPage={currentSubPage} 
              setCurrentSubPage={setCurrentSubPage} 
              onLogoutClick={handleLogout} 
            />
          </div>
        </div>

        {/* Dashboard Content Area - ප්‍රස්තාර සහ ටේබල් එක පොඩි කර තනි screen එකකට සෙට් කරන ලදි */}
        <div style={{ flex: 1, padding: '20px', display: 'flex', flexDirection: 'column', gap: '15px', overflow: 'hidden', height: '100%' }}>
          
          {/* Stat Cards Row */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '15px', flexShrink: 0 }}>
            <StatCard 
              title="Total Students" 
              value="1,250" 
              accentColor="#15803d" 
              icon={
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#15803d" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path>
                  <circle cx="9" cy="7" r="4"></circle>
                  <path d="M23 21v-2a4 4 0 0 0-3-3.87"></path>
                  <path d="M16 3.13a4 4 0 0 1 0 7.75"></path>
                </svg>
              }
            />

            <StatCard 
              title="Total Teachers" 
              value="24" 
              accentColor="#22c55e" 
              icon={
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#22c55e" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"></path>
                  <path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"></path>
                </svg>
              }
            />

            <StatCard 
              title="Active Classes" 
              value="45" 
              accentColor="#1e293b" 
              icon={
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#1e293b" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect>
                  <line x1="16" y1="2" x2="16" y2="6"></line>
                  <line x1="8" y1="2" x2="8" y2="6"></line>
                  <line x1="3" y1="10" x2="21" y2="10"></line>
                </svg>
              }
            />

            <StatCard 
              title="Today's Classes" 
              value="08" 
              accentColor="#64748b" 
              icon={
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#64748b" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <circle cx="12" cy="12" r="10"></circle>
                  <polyline points="12 6 12 12 16 14"></polyline>
                </svg>
              }
            />
          </div>

          {/* Graphs Section - උස 160px දක්වා කුඩා කර තනි screen එකකට fit කළා */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '15px', flexShrink: 0 }}>
            
            {/* 1. Enrollment Line Chart */}
            <div style={{ backgroundColor: '#fff', padding: '12px', borderRadius: '10px', boxShadow: '0 2px 4px rgba(0,0,0,0.04)' }}>
              <h4 style={{ marginTop: 0, color: '#1e293b', borderBottom: '2px solid #f1f5f9', paddingBottom: '6px', fontSize: '14px', marginBottom: '10px' }}>
                Enrollment Growth
              </h4>
              <div style={{ width: '100%', height: '160px' }}>
                <ResponsiveContainer width="100%" height="100%">
                  <LineChart data={enrollmentData} margin={{ left: -25, right: 10 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                    <XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11}} />
                    <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11}} />
                    <Tooltip contentStyle={{ borderRadius: '6px', fontSize: '12px' }} />
                    <Line type="monotone" dataKey="students" stroke="#15803d" strokeWidth={2.5} dot={{ r: 3, fill: '#15803d' }} />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            </div>

            {/* 2. Class Distribution Bar Chart */}
            <div style={{ backgroundColor: '#fff', padding: '12px', borderRadius: '10px', boxShadow: '0 2px 4px rgba(0,0,0,0.04)' }}>
              <h4 style={{ marginTop: 0, color: '#1e293b', borderBottom: '2px solid #f1f5f9', paddingBottom: '6px', fontSize: '14px', marginBottom: '10px' }}>
                Class Distribution
              </h4>
              <div style={{ width: '100%', height: '160px' }}>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={classDistributionData} margin={{ left: -25, right: 10 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                    <XAxis dataKey="grade" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10}} />
                    <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 11}} />
                    <Tooltip contentStyle={{ borderRadius: '6px', fontSize: '12px' }} />
                    <Bar dataKey="classes" fill="#22c55e" radius={[4, 4, 0, 0]} barSize={22} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>

            {/* 3. Colorful Pie Chart */}
            <div style={{ backgroundColor: '#fff', padding: '12px', borderRadius: '10px', boxShadow: '0 2px 4px rgba(0,0,0,0.04)', display: 'flex', flexDirection: 'column' }}>
              <h4 style={{ marginTop: 0, color: '#1e293b', borderBottom: '2px solid #f1f5f9', paddingBottom: '6px', fontSize: '14px', marginBottom: '10px' }}>
                Students by Subject
              </h4>
              <div style={{ flex: 1, minHeight: '120px' }}>
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={subjectData}
                      cx="50%"
                      cy="50%"
                      innerRadius={35}
                      outerRadius={50}
                      paddingAngle={4}
                      dataKey="value"
                    >
                      {subjectData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={THEME_COLORS[index % THEME_COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip contentStyle={{ borderRadius: '6px', fontSize: '12px' }} />
                  </PieChart>
                </ResponsiveContainer>
              </div>
              <div style={{ display: 'flex', justifyContent: 'center', gap: '8px', flexWrap: 'wrap' }}>
                {subjectData.map((entry, index) => (
                  <div key={index} style={{ display: 'flex', alignItems: 'center', fontSize: '10px', color: '#64748b', fontWeight: '500' }}>
                    <div style={{ width: '6px', height: '6px', backgroundColor: THEME_COLORS[index], borderRadius: '50%', marginRight: '3px' }}></div>
                    {entry.name}
                  </div>
                ))}
              </div>
            </div>

          </div>

          {/* Upcoming Class Schedule - කිසිසේත්ම scroll නොවෙන කුඩා ටේබල් එක */}
          <div style={{ backgroundColor: '#fff', padding: '12px 18px', borderRadius: '10px', boxShadow: '0 2px 4px rgba(0,0,0,0.04)', flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
            <h3 style={{ marginTop: 0, color: '#15803d', borderBottom: '2px solid #f1f5f9', paddingBottom: '6px', marginBottom: '8px', fontSize: '14px' }}>
              Upcoming Class Schedule
            </h3>
            
            <div style={{ overflowX: 'auto', width: '100%', flex: 1 }}>
              <table style={{ 
                width: '100%', 
                borderCollapse: 'collapse', 
                textAlign: 'center', 
                border: '1px solid #cbd5e1'
              }}>
                <thead>
                  <tr style={{ backgroundColor: '#f8fafc' }}>
                    <th style={{ padding: '6px 8px', color: '#1e293b', fontWeight: '700', fontSize: '11px', textAlign: 'left', border: '1px solid #cbd5e1', width: '85px' }}>Time</th>
                    <th style={{ padding: '6px 8px', color: '#1e293b', fontWeight: '700', fontSize: '11px', border: '1px solid #cbd5e1' }}>Mon</th>
                    <th style={{ padding: '6px 8px', color: '#1e293b', fontWeight: '700', fontSize: '11px', border: '1px solid #cbd5e1' }}>Tue</th>
                    <th style={{ padding: '6px 8px', color: '#1e293b', fontWeight: '700', fontSize: '12px', border: '1px solid #cbd5e1' }}>Wed</th>
                    <th style={{ padding: '6px 8px', color: '#1e293b', fontWeight: '700', fontSize: '11px', border: '1px solid #cbd5e1' }}>Thu</th>
                    <th style={{ padding: '6px 8px', color: '#1e293b', fontWeight: '700', fontSize: '11px', border: '1px solid #cbd5e1' }}>Fri</th>
                    <th style={{ padding: '6px 8px', color: '#1e293b', fontWeight: '700', fontSize: '11px', border: '1px solid #cbd5e1' }}>Sat</th>
                    <th style={{ padding: '6px 8px', color: '#1e293b', fontWeight: '700', fontSize: '11px', border: '1px solid #cbd5e1' }}>Sun</th>
                  </tr>
                </thead>
                <tbody>
                  {weeklySchedule.map((row, index) => (
                    <tr key={index}>
                      <td style={{ padding: '4px 8px', fontSize: '11px', fontWeight: '700', color: '#1e293b', textAlign: 'left', backgroundColor: '#f8fafc', border: '1px solid #cbd5e1' }}>{row.time}</td>
                      <td style={{ padding: '4px 8px', border: '1px solid #cbd5e1', backgroundColor: '#ffffff' }}><ScheduleCell text={row.mon} /></td>
                      <td style={{ padding: '4px 8px', border: '1px solid #cbd5e1', backgroundColor: '#ffffff' }}><ScheduleCell text={row.tue} /></td>
                      <td style={{ padding: '4px 8px', border: '1px solid #cbd5e1', backgroundColor: '#ffffff' }}><ScheduleCell text={row.wed} /></td>
                      <td style={{ padding: '4px 8px', border: '1px solid #cbd5e1', backgroundColor: '#ffffff' }}><ScheduleCell text={row.thu} /></td>
                      <td style={{ padding: '4px 8px', border: '1px solid #cbd5e1', backgroundColor: '#ffffff' }}><ScheduleCell text={row.fri} /></td>
                      <td style={{ padding: '4px 8px', border: '1px solid #cbd5e1', backgroundColor: '#ffffff' }}><ScheduleCell text={row.sat} /></td>
                      <td style={{ padding: '4px 8px', border: '1px solid #cbd5e1', backgroundColor: '#ffffff' }}><ScheduleCell text={row.sun} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

        </div>
      </div>
    </div>
  );
}

// --- Helper Components ---

function ScheduleCell({ text }) {
  if (text === "-") return <span style={{ color: '#94a3b8', fontSize: '10px' }}>-</span>;
  
  let bgColor = '#e0f2fe'; 
  let textColor = '#0369a1';
  
  if (text.includes("Science")) { bgColor = '#dcfce7'; textColor = '#15803d'; }
  else if (text.includes("Maths")) { bgColor = '#fef9c3'; textColor = '#a16207'; }
  else if (text.includes("Physics")) { bgColor = '#f3e8ff'; textColor = '#6b21a8'; }
  else if (text.includes("Class") || text.includes("Revision")) { bgColor = '#fee2e2'; textColor = '#991b1b'; }

  return (
    <span style={{ 
      backgroundColor: bgColor, color: textColor, 
      padding: '2px 5px', borderRadius: '4px', 
      fontWeight: '600', fontSize: '10px', display: 'inline-block', 
      minWidth: '78px', 
      boxShadow: '0 1px 2px rgba(0,0,0,0.01)'
    }}>
      {text}
    </span>
  );
}

function StatCard({ title, value, accentColor, icon }) {
  return (
    <div style={{ 
      backgroundColor: '#fff', padding: '15px', borderRadius: '10px', 
      boxShadow: '0 2px 4px rgba(0,0,0,0.04)', borderLeft: `5px solid ${accentColor}`,
      display: 'flex', justifyContent: 'space-between', alignItems: 'center'
    }}>
      <div>
        <p style={{ margin: 0, color: '#64748b', fontSize: '13px', fontWeight: '500' }}>{title}</p>
        <h2 style={{ margin: '5px 0 0 0', color: '#1e293b', fontSize: '24px' }}>{value}</h2>
      </div>
      <div style={{ opacity: 0.8 }}>{icon}</div>
    </div>
  );
}
